/**
 * Reading what the operator already has on YouTube.
 *
 * This is a separate concern from playback: the two players work with no account at all, and
 * everything here is additive. The scope is read-only, so nothing in this file can change,
 * reorder, or delete anything on the account.
 *
 * Every response is parsed defensively from `unknown`. A field the API stops sending should
 * drop one row, never throw and take the whole list with it.
 */

const API_ROOT = 'https://www.googleapis.com/youtube/v3';

/** One row in a picker list. `id` means whatever the list is made of — playlist, channel, video. */
export interface LibraryItem {
  readonly id: string;
  readonly title: string;
  readonly thumbnail: string | null;
}

function asRecord(value: unknown): Record<string, unknown> | null {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : null;
}

function readItems(payload: unknown): Record<string, unknown>[] {
  const root = asRecord(payload);
  const items = root?.items;
  if (!Array.isArray(items)) return [];
  return items.map(asRecord).filter((item): item is Record<string, unknown> => item !== null);
}

function readTitle(snippet: Record<string, unknown> | null): string | null {
  const title = snippet?.title;
  return typeof title === 'string' && title.length > 0 ? title : null;
}

/**
 * The API offers several sizes under `thumbnails`. Preference order is deliberate: `medium`
 * is the smallest that stays sharp on a phone, and falling back to `default` keeps a row
 * visible rather than blank when only the tiny one exists.
 */
function readThumbnail(snippet: Record<string, unknown> | null): string | null {
  const thumbnails = asRecord(snippet?.thumbnails);
  if (thumbnails === null) return null;
  for (const size of ['medium', 'default', 'high']) {
    const url = asRecord(thumbnails[size])?.url;
    if (typeof url === 'string' && url.length > 0) return url;
  }
  return null;
}

/** Pulls a nested string, e.g. `resourceId.videoId`, without trusting any level of the path. */
function readNestedId(snippet: Record<string, unknown> | null, key: string): string | null {
  const resource = asRecord(snippet?.resourceId);
  const id = resource?.[key];
  return typeof id === 'string' && id.length > 0 ? id : null;
}

function readTopLevelId(item: Record<string, unknown>): string | null {
  const { id } = item;
  return typeof id === 'string' && id.length > 0 ? id : null;
}

function toItem(id: string | null, snippet: Record<string, unknown> | null): LibraryItem | null {
  const title = readTitle(snippet);
  if (id === null || title === null) return null;
  return { id, title, thumbnail: readThumbnail(snippet) };
}

/** The operator's own playlists. `id` is a playlist id, to be passed back to `parsePlaylistItems`. */
export function parsePlaylists(payload: unknown): LibraryItem[] {
  return readItems(payload)
    .map((item) => toItem(readTopLevelId(item), asRecord(item.snippet)))
    .filter((item): item is LibraryItem => item !== null);
}

/** Videos inside one playlist. `id` is a video id, ready for a slot. */
export function parsePlaylistItems(payload: unknown): LibraryItem[] {
  return readItems(payload)
    .map((item) => {
      const snippet = asRecord(item.snippet);
      return toItem(readNestedId(snippet, 'videoId'), snippet);
    })
    .filter((item): item is LibraryItem => item !== null);
}

/** Subscribed channels. `id` is a channel id, to be passed back to `parseSearchResults`. */
export function parseSubscriptions(payload: unknown): LibraryItem[] {
  return readItems(payload)
    .map((item) => {
      const snippet = asRecord(item.snippet);
      return toItem(readNestedId(snippet, 'channelId'), snippet);
    })
    .filter((item): item is LibraryItem => item !== null);
}

/** Videos from `videos` (liked). `id` is a video id. */
export function parseVideos(payload: unknown): LibraryItem[] {
  return readItems(payload)
    .map((item) => toItem(readTopLevelId(item), asRecord(item.snippet)))
    .filter((item): item is LibraryItem => item !== null);
}

/** Videos from `search`. Unlike the lists above, the id is an object, not a string. */
export function parseSearchResults(payload: unknown): LibraryItem[] {
  return readItems(payload)
    .map((item) => {
      const id = asRecord(item.id)?.videoId;
      const videoId = typeof id === 'string' && id.length > 0 ? id : null;
      return toItem(videoId, asRecord(item.snippet));
    })
    .filter((item): item is LibraryItem => item !== null);
}

export class YouTubeApiError extends Error {
  constructor(
    readonly status: number,
    message: string,
    /**
     * Google's own word for why, e.g. `quotaExceeded`. Null when it did not say. The status
     * alone is not enough: a refused token and a spent search budget are both 403, and telling
     * someone to sign in again when the real answer is "tomorrow" sends them in a circle.
     */
    readonly reason: string | null = null,
  ) {
    super(message);
    this.name = 'YouTubeApiError';
  }
}

/** Reads Google's machine-readable reason out of an error body. Never throws. */
export function parseErrorReason(payload: unknown): string | null {
  const errors = asRecord(asRecord(payload)?.error)?.errors;
  if (!Array.isArray(errors)) return null;
  const reason = asRecord(errors[0])?.reason;
  return typeof reason === 'string' && reason.length > 0 ? reason : null;
}

async function get(path: string, params: Record<string, string>, token: string): Promise<unknown> {
  const url = new URL(`${API_ROOT}/${path}`);
  for (const [key, value] of Object.entries(params)) url.searchParams.set(key, value);

  const response = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
  if (!response.ok) {
    const body: unknown = await response.json().catch(() => null);
    throw new YouTubeApiError(
      response.status,
      `${path} が ${response.status} を返しました`,
      parseErrorReason(body),
    );
  }
  return response.json();
}

const PAGE_SIZE = '50';

export async function fetchPlaylists(token: string): Promise<LibraryItem[]> {
  return parsePlaylists(
    await get('playlists', { part: 'snippet', mine: 'true', maxResults: PAGE_SIZE }, token),
  );
}

export async function fetchPlaylistItems(
  token: string,
  playlistId: string,
): Promise<LibraryItem[]> {
  return parsePlaylistItems(
    await get('playlistItems', { part: 'snippet', playlistId, maxResults: PAGE_SIZE }, token),
  );
}

export async function fetchSubscriptions(token: string): Promise<LibraryItem[]> {
  return parseSubscriptions(
    await get(
      'subscriptions',
      { part: 'snippet', mine: 'true', maxResults: PAGE_SIZE, order: 'alphabetical' },
      token,
    ),
  );
}

/**
 * What is popular in Japan right now.
 *
 * This is the nearest thing the API has to おすすめ, and it is deliberately not the same
 * thing: YouTube's own recommendations are built from the operator's history, and the Data
 * API has never exposed either. Google's own revision history says it plainly —
 * 「ユーザーの再生履歴とおすすめリストには API を介してアクセスできません」 — and the one
 * endpoint that came close, `search.list` with `relatedToVideoId`, was switched off on
 * 2023-08-07. So this list is the same for everybody, and the tab says so.
 *
 * One quota unit, where a search costs a hundred.
 */
export async function fetchPopularVideos(token: string): Promise<LibraryItem[]> {
  return parseVideos(
    await get(
      'videos',
      { part: 'snippet', chart: 'mostPopular', regionCode: 'JP', maxResults: PAGE_SIZE },
      token,
    ),
  );
}

export async function fetchLikedVideos(token: string): Promise<LibraryItem[]> {
  return parseVideos(
    await get('videos', { part: 'snippet', myRating: 'like', maxResults: PAGE_SIZE }, token),
  );
}

/**
 * Recent uploads from one channel.
 *
 * `search` costs 100 quota units against the 10,000 per day, where a plain list costs 1. That is
 * still ~100 channel opens a day, far past what one person does, and the alternative (resolving
 * the channel's uploads playlist first) costs an extra round trip on every single open.
 */
export async function fetchChannelVideos(token: string, channelId: string): Promise<LibraryItem[]> {
  return parseSearchResults(
    await get(
      'search',
      { part: 'snippet', channelId, order: 'date', type: 'video', maxResults: '25' },
      token,
    ),
  );
}

/**
 * Free text search across YouTube.
 *
 * The only entrance that asks for nothing the operator already holds — no address, no id, and
 * no requirement that the video be in their own account. Without it, someone who simply knows
 * a song's name has no way to start at all.
 *
 * Same 100 units per call as above, so roughly 100 searches a day against the 10,000 budget.
 * Running out arrives as a 403 carrying `quotaExceeded`, which the panel says plainly rather
 * than showing an empty list.
 */
export async function searchVideos(token: string, query: string): Promise<LibraryItem[]> {
  return parseSearchResults(
    await get('search', { part: 'snippet', q: query, type: 'video', maxResults: '25' }, token),
  );
}
