import './ui/styles.css';
import { startApp } from './ui/app.js';

void startApp();

/**
 * Register the offline shell only in a real build.
 *
 * In development a service worker would serve yesterday's bundle over today's edits, which
 * wastes an afternoon before anyone suspects it. The worker exists for one reason — the app
 * is served off the operator's Mac, so the Mac sleeping must not take the app down with it.
 */
if (import.meta.env.PROD && 'serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    void navigator.serviceWorker.register('/sw.js').catch(() => {
      // Offline support is a convenience. Losing it must not break playback.
    });
  });
}
