/**
 * The update button.
 *
 * Installed on the tablet as a real app, there is no address bar and no reload button. Android
 * keeps the app alive in the background and only re-reads the page on a cold start, so the only
 * way to pick up a new build was to kill the app from the task switcher — every time (operator,
 * 2026-09-23: 毎回タスクキルするのが嫌だ).
 *
 * So the app asks. `version.json` is written by the build and never cached (`public/sw.js`), and
 * the answer is compared with what is running. The button also wears a dot when a quiet check
 * has already found something, because a button nobody thinks to press is no better than the
 * task switcher.
 */

import { type BuildStamp, isDifferentBuild, parseBuildStamp } from '../core/build-stamp.js';

const STAMP_URL = '/version.json';

/** How often the quiet check may actually go to the network. */
const QUIET_CHECK_GAP_MS = 60_000;

export interface UpdateHost {
  /** Where the app says things to the operator. */
  readonly say: (text: string) => void;
}

/** Never throws, and never rejects: no network is an ordinary answer here. */
async function fetchServedStamp(): Promise<BuildStamp | null> {
  try {
    const response = await fetch(STAMP_URL, { cache: 'no-store' });
    if (!response.ok) return null;
    return parseBuildStamp(await response.json());
  } catch {
    return null;
  }
}

/**
 * Hands the page over to the new build.
 *
 * The worker is told to stop waiting first, so the reload lands on the new one rather than
 * being served by the old one and needing a second reload. If any of that fails the reload
 * still happens: the page itself is fetched from the network before the cache, so a plain
 * reload is already most of the answer.
 */
async function takeUpdate(): Promise<void> {
  try {
    const registration = await navigator.serviceWorker?.getRegistration();
    if (registration !== undefined) {
      await registration.update();
      registration.waiting?.postMessage('skip-waiting');
    }
  } catch {
    // Nothing to do: the reload below is what actually brings the new build in.
  }
  window.location.reload();
}

export function wireUpdate(button: HTMLButtonElement, host: UpdateHost): void {
  const running: BuildStamp = { version: __APP_VERSION__, sha: __GIT_SHA__ };
  let checking = false;
  let lastCheck = 0;

  const markAvailable = (available: boolean): void => {
    button.classList.toggle('has-update', available);
    button.title = available ? '新しい版があります' : '更新を確認';
  };

  /** In the background: no messages, no spinner, just the dot if there is something. */
  const quietCheck = async (): Promise<void> => {
    const now = Date.now();
    if (checking || now - lastCheck < QUIET_CHECK_GAP_MS) return;
    lastCheck = now;
    const served = await fetchServedStamp();
    if (served !== null) markAvailable(isDifferentBuild(running, served));
  };

  button.addEventListener('click', () => {
    if (checking) return;
    checking = true;
    lastCheck = Date.now();
    host.say('更新を確認しています…');

    void fetchServedStamp().then((served) => {
      checking = false;
      if (served === null) {
        host.say('いま更新を確認できません。通信を確かめてください。');
        return;
      }
      if (!isDifferentBuild(running, served)) {
        markAvailable(false);
        host.say(`最新です (v${running.version})。`);
        return;
      }
      markAvailable(true);
      host.say(`v${served.version} に入れ替えます…`);
      void takeUpdate();
    });
  });

  // Coming back to the app is exactly when a new build may have appeared since last time.
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') void quietCheck();
  });
  void quietCheck();
}
