/**
 * Wiring the slots to the page.
 *
 * The one rule that shapes this file: a slot never touches its neighbour. "Play all" is a
 * single tap that sends play to each slot in turn, which is what browsers require for audible
 * playback — one gesture, then commands. It is not a combined player, and it never was; that
 * is exactly why growing from two slots to twenty needed no change to how playing works.
 *
 * Slots are built on demand: two on an ordinary visit, and the rest only when the operator
 * turns the count up. Twenty players started on every visit would be a heavy price for a
 * screen most visits never look at. Built slots are never thrown away — turning the count
 * back down hides and pauses them, so turning it up again costs nothing.
 */

import { GoogleAuth, describeSignInFailure } from '../auth/google.js';
import {
  DEFAULT_SESSION,
  type Layout,
  MAX_SLOTS,
  STORAGE_KEY,
  type SessionState,
  type SlotSettings,
  applyLinkOverrides,
  clampCount,
  defaultVolumeFor,
  layoutFor,
  parseSession,
  serializeSession,
} from '../core/session.js';
import { NORMAL_SPEED, describeSpeed, stepSpeed } from '../core/speed.js';
import { MIN_COLUMNS_FOR_HANDLE, dragWidths, evenWidths } from '../core/split.js';
import { parseVideoId } from '../core/video-id.js';
import { MAX_VOLUME, MIN_VOLUME } from '../core/volume.js';
import { DEFAULT_RATIO, fetchVideoRatio } from '../youtube/shape.js';
import { Slot, type SlotStatus } from '../youtube/slot.js';
import { columnsFor } from './columns.js';
import { must } from './dom.js';
import { fillScaleFor } from './gesture-math.js';
import { attachGestures } from './gestures.js';
import { LibraryPanel, type PickTarget } from './library.js';
import { wireUpdate } from './update.js';

/** One press of an arrow key on the divider: a twentieth of the row. */
const SPLIT_STEP = 0.05;

const STATUS_LABEL: Record<SlotStatus, string> = {
  loading: '読み込み中',
  empty: '動画が未指定',
  ready: '準備完了',
  playing: '再生中',
  paused: '一時停止',
  ended: '終了',
  error: '再生できません',
};

interface SlotElements {
  readonly section: HTMLElement;
  readonly name: HTMLButtonElement;
  readonly mount: HTMLElement;
  readonly frame: HTMLElement;
  readonly status: HTMLElement;
  readonly input: HTMLInputElement;
  readonly load: HTMLButtonElement;
  /** Opens and folds away the address box, which is otherwise only out on an empty slot. */
  readonly pasteToggle: HTMLButtonElement;
  /**
   * Play and pause in one button, the way the full-screen bar already works. Two buttons
   * meant one of them was always the dead one, and two buttons is two widths of a narrow row.
   */
  readonly toggle: HTMLButtonElement;
  /** The whole picture, tappable, while the slot has not started. */
  readonly start: HTMLButtonElement;
  readonly mute: HTMLButtonElement;
  readonly loop: HTMLButtonElement;
  readonly expand: HTMLButtonElement;
  readonly collapse: HTMLButtonElement;
  readonly gesture: HTMLElement;
  readonly hint: HTMLElement;
  /** The playback bar and its parts, shown only while this slot is full screen. */
  readonly barPlay: HTMLButtonElement;
  readonly elapsed: HTMLElement;
  readonly seek: HTMLInputElement;
  readonly total: HTMLElement;
  readonly speed: HTMLSelectElement;
  readonly volume: HTMLInputElement;
  readonly volumeValue: HTMLOutputElement;
}

function readSlotElements(section: HTMLElement): SlotElements {
  return {
    section,
    name: must<HTMLButtonElement>(section, '[data-select]'),
    mount: must<HTMLElement>(section, '[data-mount]'),
    frame: must<HTMLElement>(section, '.frame'),
    status: must<HTMLElement>(section, '[data-status]'),
    input: must<HTMLInputElement>(section, '[data-input]'),
    load: must<HTMLButtonElement>(section, '[data-load]'),
    pasteToggle: must<HTMLButtonElement>(section, '[data-paste-toggle]'),
    start: must<HTMLButtonElement>(section, '[data-start]'),
    toggle: must<HTMLButtonElement>(section, '[data-toggle]'),
    mute: must<HTMLButtonElement>(section, '[data-mute]'),
    loop: must<HTMLButtonElement>(section, '[data-loop]'),
    expand: must<HTMLButtonElement>(section, '[data-expand]'),
    collapse: must<HTMLButtonElement>(section, '[data-collapse]'),
    gesture: must<HTMLElement>(section, '[data-gesture]'),
    hint: must<HTMLElement>(section, '[data-hint]'),
    barPlay: must<HTMLButtonElement>(section, '[data-bar-play]'),
    elapsed: must<HTMLElement>(section, '[data-elapsed]'),
    seek: must<HTMLInputElement>(section, '[data-seek]'),
    total: must<HTMLElement>(section, '[data-total]'),
    speed: must<HTMLSelectElement>(section, '[data-speed]'),
    volume: must<HTMLInputElement>(section, '[data-volume]'),
    volumeValue: must<HTMLOutputElement>(section, '[data-volume-value]'),
  };
}

/**
 * The first two keep the names the app was built around; the rest are just numbered. Calling
 * slot 7 "音楽" would be a lie, and calling slot 1 "1" would throw away the one thing that
 * tells the operator which of the two is which.
 */
function slotName(index: number, layout: Layout): string {
  if (layout === 'wall') return String(index + 1);
  if (index === 0) return '動画';
  if (index === 1) return '音楽';
  return String(index + 1);
}

/** Storage can be unavailable (private mode, blocked site data); that must not break playback. */
function readStoredSession(): SessionState {
  try {
    return parseSession(window.localStorage.getItem(STORAGE_KEY));
  } catch {
    return DEFAULT_SESSION;
  }
}

function writeStoredSession(session: SessionState): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, serializeSession(session));
  } catch {
    // Nothing to do: remembering the pair is a convenience, not a requirement.
  }
}

/**
 * Signing in is optional and always late.
 *
 * The players are already running by the time anyone taps this button, and every failure path
 * here ends by leaving the app exactly as it was. Someone who never signs in loses nothing and
 * never even fetches Google's script.
 */
interface LibraryHost {
  readonly place: (videoId: string, target: PickTarget) => string;
  readonly fillAll: (videoIds: readonly string[]) => string;
  readonly layout: () => Layout;
}

function wireLibrary(note: HTMLElement, host: LibraryHost): void {
  const auth = new GoogleAuth();
  const signIn = must<HTMLButtonElement>(document, '#signIn');

  // Google's script has to be here before the tap, not fetched during it — a browser only
  // lets a page open a window while it is still handling a real touch. Anyone who never
  // touches the page never fetches it.
  document.addEventListener('pointerdown', () => auth.prime(), { once: true, passive: true });

  const library = new LibraryPanel(auth, {
    onPick: (videoId, target) => {
      note.textContent = host.place(videoId, target);
    },
    onFillAll: (videoIds) => {
      note.textContent = host.fillAll(videoIds);
    },
    layout: host.layout,
    onSignInNeeded: () => {
      // YouTube turned down a token that was fetched successfully, so the consent behind it
      // is not what it was. Dropping the note is what puts ログイン back on the button.
      auth.forgetConsent();
      reflect();
    },
  });

  /**
   * A token lasts about an hour; consent lasts until it is withdrawn. The button follows
   * consent, not the token — an expired token is replaced without asking anyone, and saying
   * ログイン for it would make the operator tap through a sign-in they never needed. When a
   * request finds that consent really is gone, `onSignInNeeded` brings the button back.
   */
  const reflect = (): void => {
    signIn.textContent = auth.isSignedIn() || auth.hasConsented() ? '一覧' : 'ログイン';
  };

  signIn.addEventListener('click', () => {
    if (auth.isSignedIn() || auth.hasConsented()) {
      if (library.isOpen) library.close();
      else library.open();
      return;
    }

    // The popup only opens if it is still inside this tap, so nothing may be awaited first.
    // If the script is not here yet, spend this tap on fetching it and ask for another one —
    // opening the window after a network wait is what the browser refuses.
    if (!auth.isReady()) {
      auth.prime();
      note.textContent = '準備中です。もう一度押してください。';
      return;
    }

    signIn.disabled = true;
    void auth
      .signIn()
      .then(() => {
        note.textContent = '';
        reflect();
        library.open();
      })
      .catch((error: unknown) => {
        note.textContent = describeSignInFailure(error);
      })
      .finally(() => {
        signIn.disabled = false;
      });
  });

  // Consented before on this device? Then the button should already say so, untapped.
  void auth.trySilent().then(reflect);
}

/** One slot, once it exists on the page: the player, its controls, and how to fill it. */
interface BuiltSlot {
  readonly slot: Slot;
  readonly elements: SlotElements;
  readonly load: (videoId: string) => void;
  /** Recomputes how far to enlarge the picture to cover the frame it is now sitting in. */
  readonly refit: () => void;
  /**
   * Sets the volume the way this slot's own slider does — player, slider, reading and saved
   * session together. Returns what the player settled on.
   *
   * Exposed for the drawer that reaches other slots while one is full screen. Changing the
   * player alone would leave the slider behind, and the difference would only show up when
   * full screen ended.
   */
  readonly setVolume: (value: number) => number;
  /** Says something briefly over the picture, the way the gestures announce themselves. */
  readonly flash: (text: string) => void;
  /** Brings the full-screen playback bar up to date with where the video actually is. */
  readonly syncBar: () => void;
  /** Empties this slot and puts its settings back to the ones it started life with. */
  readonly reset: () => void;
  /**
   * Re-decides whether the address box is out. It depends on the layout as well as on this
   * slot, so the count has to be able to ask for it again.
   */
  readonly reflectPaste: () => void;
}

/**
 * Seconds as a clock reads them. An hour-long video gets its hours; a short does not, because
 * a leading `0:` on every line is three characters that never say anything.
 */
function clock(seconds: number): string {
  const whole = Math.max(0, Math.floor(seconds));
  const s = String(whole % 60).padStart(2, '0');
  const m = Math.floor(whole / 60) % 60;
  const h = Math.floor(whole / 3600);
  return h > 0 ? `${h}:${String(m).padStart(2, '0')}:${s}` : `${m}:${s}`;
}

export async function startApp(): Promise<void> {
  must<HTMLElement>(document, '#version').textContent = `v${__APP_VERSION__} ${__GIT_SHA__}`;

  const note = must<HTMLElement>(document, '#note');
  const host = must<HTMLElement>(document, '#slots');
  const template = must<HTMLTemplateElement>(document, '#slotTemplate');
  const range = must<HTMLInputElement>(document, '#countRange');
  const countValue = must<HTMLOutputElement>(document, '#countValue');

  const columnsSelect = must<HTMLSelectElement>(document, '#columnsSelect');
  const mixerOpen = must<HTMLButtonElement>(document, '#mixerOpen');
  const mixer = must<HTMLElement>(document, '#mixer');
  const mixerList = must<HTMLElement>(document, '#mixerList');

  wireUpdate(must<HTMLButtonElement>(document, '#update'), {
    say: (text) => {
      note.textContent = text;
    },
  });

  const stored = applyLinkOverrides(readStoredSession(), window.location.search);
  const settings: SlotSettings[] = [...stored.slots];
  let count = stored.count;
  let columns: number | null = stored.columns;
  /** How the width is shared between the columns, kept per column count. */
  let widths: Record<number, readonly number[]> = { ...stored.widths };
  let layout: Layout = layoutFor(count);
  /** Which slot the picker fills next, on the wall. The pair names its two targets instead. */
  let selected = 0;
  /** Which slot is covering the page, if any. */
  let expanded: number | null = null;
  /**
   * Whether going full screen pushed a history entry that is still there.
   *
   * On a phone or tablet the back gesture is how anything covering the screen is dismissed, and
   * without an entry of our own it leaves the app instead — every other slot stops with it.
   * The flag is what keeps a close from stepping back too far: `history.back()` is only right
   * while our own entry is the one on top.
   */
  let expandPushedHistory = false;

  const built: BuiltSlot[] = [];

  const save = (): void => {
    writeStoredSession({ count, columns, slots: settings, widths });
  };

  const at = (index: number): SlotSettings =>
    settings[index] ?? {
      videoId: null,
      volume: defaultVolumeFor(index),
      speed: NORMAL_SPEED,
      loop: true,
    };

  function buildSlot(index: number): BuiltSlot {
    const section = template.content.firstElementChild?.cloneNode(true);
    if (!(section instanceof HTMLElement)) throw new Error('markup is missing #slotTemplate');
    host.append(section);

    const elements = readSlotElements(section);
    const initial = at(index);

    let lastErrorCode: number | null = null;

    const slot = new Slot(elements.mount, initial, {
      onStatusChange: (status) => {
        if (status !== 'error') lastErrorCode = null;
        // The stylesheet needs the state as something it can match on: the gesture guide
        // shows itself while this slot is full screen and paused, and text in a <span> is
        // not something CSS can read.
        elements.section.dataset.state = status;
        elements.status.textContent =
          status === 'error' && lastErrorCode !== null
            ? `${STATUS_LABEL.error} (コード ${lastErrorCode})`
            : STATUS_LABEL[status];
        // One button for both, so its face has to say which way it will go next.
        const playing = status === 'playing';
        elements.toggle.textContent = playing ? '⏸' : '▶';
        elements.toggle.title = playing ? '一時停止' : '再生';
        elements.toggle.setAttribute('aria-label', elements.toggle.title);
      },
      onError: (code) => {
        lastErrorCode = code;
      },
    });

    if (initial.videoId !== null) elements.input.value = initial.videoId;
    elements.volume.value = String(initial.volume);
    elements.volumeValue.value = String(initial.volume);
    elements.speed.value = String(initial.speed);
    elements.loop.setAttribute('aria-pressed', String(initial.loop));

    /**
     * The mute button keeps one glyph and changes its state, rather than swapping 🔇 for 🔊.
     * Two speaker glyphs a few pixels apart, one of them next to a volume slider, is a
     * puzzle; a button that lights up when it is on is not.
     */
    const reflectMute = (muted: boolean): void => {
      elements.mute.setAttribute('aria-pressed', String(muted));
      elements.mute.title = muted ? '消音を解除' : '消音';
      elements.mute.setAttribute('aria-label', elements.mute.title);
    };

    /**
     * Whether the address box is out.
     *
     * Opened by 🔗, and opened by itself on a pair slot with nothing in it — that is the one
     * moment it is the only way in, and the moment its width is not being wasted. Never by
     * itself on the wall: twenty empty slots would be twenty address boxes, which is what
     * the picker exists to avoid.
     */
    let pasteOpen = false;

    const reflectPaste = (): void => {
      const auto = layout === 'pair' && at(index).videoId === null;
      elements.section.dataset.paste = pasteOpen || auto ? 'on' : 'off';
      elements.pasteToggle.setAttribute('aria-pressed', String(pasteOpen));
    };

    elements.pasteToggle.addEventListener('click', () => {
      pasteOpen = !pasteOpen;
      reflectPaste();
      if (pasteOpen) elements.input.focus();
    });

    /**
     * Reshape the frame to match the video. Guarded by a counter because a second video can
     * be loaded before the first answers, and a late answer must never repaint a frame the
     * operator has already moved on from. The old shape stays until the new one is known —
     * clearing it first would make every load flash through 16:9 on the way.
     */
    let shapeRequest = 0;
    let videoRatio = DEFAULT_RATIO;

    /**
     * How much to enlarge the picture to cover a full screen of a different shape. Only used
     * while filling; fitting leaves it alone and lets the black bars show.
     */
    const refit = (): void => {
      const box = elements.frame.getBoundingClientRect();
      const frameRatio = box.height > 0 ? box.width / box.height : videoRatio;
      elements.frame.style.setProperty(
        '--fill-scale',
        String(fillScaleFor(videoRatio, frameRatio)),
      );
    };

    const reshape = (videoId: string): void => {
      const request = ++shapeRequest;
      void fetchVideoRatio(videoId).then((ratio) => {
        if (request !== shapeRequest) return;
        videoRatio = ratio;
        elements.frame.style.setProperty('--ratio', String(ratio));
        // A tall picture leaves the width of the screen unused while pushing its own controls
        // off the bottom of it. The stylesheet moves them alongside the picture instead, and
        // this is the only place that knows which shape arrived.
        elements.section.dataset.shape = ratio < 1 ? 'tall' : 'wide';
        refit();
      });
    };

    const load = (videoId: string): void => {
      elements.input.value = videoId;
      slot.cue(videoId);
      reshape(videoId);
      settings[index] = { ...at(index), videoId };
      save();
      // Filled now, so the box has done its job and can get out of the picture's way.
      pasteOpen = false;
      reflectPaste();
    };

    if (initial.videoId !== null) reshape(initial.videoId);
    reflectPaste();

    elements.name.addEventListener('click', () => {
      selected = index;
      reflectSelection();
    });

    const loadTyped = (): void => {
      const videoId = parseVideoId(elements.input.value);
      if (videoId === null) {
        note.textContent = 'その文字列から動画が読み取れません。アドレスをそのまま貼ってください。';
        return;
      }
      note.textContent = '';
      load(videoId);
    };

    elements.load.addEventListener('click', loadTyped);
    // A phone keyboard offers 完了 where the eye is already looking; reaching back up to a
    // 40px button beside the box is the longer way round to the same thing.
    elements.input.addEventListener('keydown', (event) => {
      if (event.key !== 'Enter') return;
      event.preventDefault();
      loadTyped();
    });

    elements.toggle.addEventListener('click', () => {
      if (slot.isPlaying()) slot.pause();
      else slot.play();
    });
    elements.start.addEventListener('click', () => {
      slot.play();
    });

    elements.mute.addEventListener('click', () => {
      const muted = !slot.isMuted();
      slot.setMuted(muted);
      reflectMute(muted);
    });

    elements.loop.addEventListener('click', () => {
      const looping = !slot.isLooping();
      slot.setLooping(looping);
      elements.loop.setAttribute('aria-pressed', String(looping));
      settings[index] = { ...at(index), loop: looping };
      save();
    });

    /**
     * Both the controls and the gestures change the same two things, and both have to leave
     * the player, the controls and the stored settings agreeing. One way in, for each.
     */
    const applySpeed = (value: number): number => {
      const applied = slot.setSpeed(value);
      elements.speed.value = String(applied);
      settings[index] = { ...at(index), speed: applied };
      save();
      return applied;
    };

    const applyVolume = (value: number): number => {
      const applied = slot.setVolume(value);
      elements.volume.value = String(applied);
      elements.volumeValue.value = String(applied);
      settings[index] = { ...at(index), volume: applied };
      save();
      return applied;
    };

    elements.speed.addEventListener('change', () => {
      applySpeed(Number(elements.speed.value));
    });

    elements.volume.addEventListener('input', () => {
      applyVolume(Number(elements.volume.value));
    });

    // --- full screen, and the gestures that only exist there ---

    elements.expand.addEventListener('click', () => {
      openExpanded(index);
    });

    // The close button sits on the gesture sheet, so its touches would also be counted as a
    // tap on the picture and pause the video on the way out.
    for (const name of ['pointerdown', 'pointerup'] as const) {
      elements.collapse.addEventListener(name, (event) => {
        event.stopPropagation();
      });
    }
    elements.collapse.addEventListener('click', (event) => {
      event.stopPropagation();
      closeExpanded();
    });

    /*
     * The playback bar. Its buttons sit on the gesture sheet, so every touch that lands on
     * one would otherwise also be counted as a tap on the picture behind it.
     */
    for (const name of ['pointerdown', 'pointerup'] as const) {
      elements.barPlay.addEventListener(name, (event) => {
        event.stopPropagation();
      });
      elements.seek.addEventListener(name, (event) => {
        event.stopPropagation();
      });
    }

    elements.barPlay.addEventListener('click', (event) => {
      event.stopPropagation();
      if (slot.isPlaying()) slot.pause();
      else slot.play();
    });

    /*
     * While a thumb is on the slider the clock must stop writing to it, or every tick drags
     * the handle back to where the video still is and the thumb can never get anywhere.
     */
    let scrubbing = false;
    elements.seek.addEventListener('pointerdown', () => {
      scrubbing = true;
    });
    elements.seek.addEventListener('input', () => {
      elements.elapsed.textContent = clock(Number(elements.seek.value));
    });
    const endScrub = (): void => {
      if (!scrubbing) return;
      scrubbing = false;
      slot.seek(Number(elements.seek.value));
    };
    elements.seek.addEventListener('change', endScrub);
    elements.seek.addEventListener('pointerup', endScrub);
    elements.seek.addEventListener('pointercancel', endScrub);

    const syncBar = (): void => {
      elements.barPlay.textContent = slot.isPlaying() ? '⏸' : '▶';
      const length = slot.length();
      elements.total.textContent = clock(length);
      // A cued video has no length yet, and a slider whose end is 0 cannot be dragged
      // anywhere; it simply waits, which is the honest thing for it to show.
      elements.seek.max = String(Math.max(0, Math.round(length)));
      if (scrubbing) return;
      const at = slot.position();
      elements.seek.value = String(Math.round(at));
      elements.elapsed.textContent = clock(at);
    };

    /** Gestures leave no trace on screen, so each one says what it just did. */
    let hintTimer: number | null = null;
    const flash = (text: string): void => {
      elements.hint.textContent = text;
      if (hintTimer !== null) window.clearTimeout(hintTimer);
      hintTimer = window.setTimeout(() => {
        elements.hint.textContent = '';
      }, 900);
    };

    attachGestures(elements.gesture, {
      currentVolume: () => slot.getVolume(),
      currentFit: () => (elements.frame.dataset.fit === 'fill' ? 'fill' : 'fit'),
      onNeighbour: (direction) => {
        wake();
        showNeighbour(index, direction);
      },
      /**
       * A single tap shows the controls, or puts them away again (operator, 2026-09-23).
       *
       * This is the third answer to the same question, and the operator's own: on 2026-09-22
       * a tap played or paused, which left the playback bar with no way in — YouTube's own bar
       * is under the gesture sheet and cannot be reached. Playing and pausing moved to the ▶
       * on that bar, one tap further away, which is how every video player behaves.
       */
      onToggle: () => {
        if (document.body.dataset.idle === '1') {
          syncBar();
          wake();
        } else {
          sleep();
        }
      },
      onSeek: (seconds) => {
        wake();
        slot.nudge(seconds);
        flash(`${seconds > 0 ? '+' : '−'}${Math.abs(seconds)} 秒`);
      },
      onSpeedStep: (steps) => {
        wake();
        const applied = applySpeed(stepSpeed(slot.getSpeed(), steps));
        flash(describeSpeed(applied));
      },
      onVolume: (volume) => {
        wake();
        flash(`音量 ${applyVolume(volume)}`);
      },
      onFit: (mode) => {
        wake();
        elements.frame.dataset.fit = mode;
        refit();
        flash(mode === 'fill' ? '画面いっぱい' : '全体を表示');
      },
      /**
       * Two fingers: the volume drawer, every slot's own included (operator, 2026-09-22).
       *
       * Mute moved to three fingers in the same change. Two fingers is the commoner gesture
       * and the drawer is the commoner errand — reaching for the corner button to change a
       * volume is the thing full screen made awkward in the first place.
       */
      onTwoFingerTap: () => {
        wake();
        toggleMixer();
      },
      onThreeFingerTap: () => {
        wake();
        const muted = !slot.isMuted();
        slot.setMuted(muted);
        reflectMute(muted);
        flash(muted ? '🔇 消音' : '🔊 消音を解除');
      },
      onDismiss: () => {
        closeExpanded();
      },
    });

    /**
     * Back to how this slot looked before anything was put in it: no video, ordinary speed,
     * looping on, sound on, and the volume this slot starts life with.
     *
     * The settings go too, not just the video. A slot left at quarter volume and half speed
     * after a reset would look empty and behave like it was still carrying the last thing in
     * it — the operator would have to find that out by playing something.
     */
    const reset = (): void => {
      slot.clear();
      slot.setMuted(false);
      slot.setLooping(true);
      elements.input.value = '';
      reflectMute(false);
      elements.loop.setAttribute('aria-pressed', 'true');
      elements.frame.dataset.fit = 'fit';
      settings[index] = {
        videoId: null,
        volume: defaultVolumeFor(index),
        speed: NORMAL_SPEED,
        loop: true,
      };
      applySpeed(NORMAL_SPEED);
      applyVolume(defaultVolumeFor(index));
      // An empty frame has no video to take its shape from, so it goes back to the default.
      // The counter is bumped so a load still in flight cannot repaint it afterwards.
      shapeRequest += 1;
      videoRatio = DEFAULT_RATIO;
      elements.frame.style.setProperty('--ratio', String(DEFAULT_RATIO));
      elements.section.dataset.shape = 'wide';
      refit();
      // Empty again, so the address box comes back out: it is the only way into an empty slot.
      pasteOpen = false;
      reflectPaste();
    };

    return {
      slot,
      elements,
      load,
      refit,
      setVolume: applyVolume,
      flash,
      syncBar,
      reset,
      reflectPaste,
    };
  }

  /**
   * Full screen is one slot covering the page, not the browser's own full-screen mode: that
   * hands the picture to YouTube's player, gestures and all, and there would be nowhere left
   * to put ours. Every other slot keeps playing, which is the whole point of the app.
   */
  /**
   * Hiding the controls over a full-screen picture once the hand has been still for a while,
   * and bringing them back.
   *
   * A single tap on the picture is what shows them and what puts them away again (operator,
   * 2026-09-23); every other gesture shows them as a side effect of doing its own job. They
   * also go on their own after a few seconds, because full screen is for watching.
   */
  const IDLE_AFTER_MS = 3000;
  let idleTimer: number | null = null;

  function wake(): void {
    document.body.dataset.idle = '0';
    if (idleTimer !== null) window.clearTimeout(idleTimer);
    // While the drawer is open its own button must stay put: the hand is already there.
    if (!mixer.hidden || expanded === null) return;
    idleTimer = window.setTimeout(() => {
      document.body.dataset.idle = '1';
    }, IDLE_AFTER_MS);
  }

  /** Puts the controls away now, rather than waiting out the few seconds. */
  function sleep(): void {
    if (idleTimer !== null) window.clearTimeout(idleTimer);
    idleTimer = null;
    document.body.dataset.idle = '1';
  }

  /**
   * Asks the browser for the whole screen as well.
   *
   * This is the page going full screen, not the player: the 2026-09-21 decision against the
   * browser's own full screen was about calling it on the YouTube frame, which hands the
   * picture and every touch on it back to YouTube. Asking for it on the page keeps the
   * gesture sheet exactly where it is, and takes the system's own bars with it — the status
   * icons above and the navigation bar below, which the operator asked to be rid of.
   *
   * Every failure is ignored: not every browser allows it, and none of it is required for
   * full screen to work.
   */
  function requestScreen(on: boolean): void {
    try {
      if (on) {
        if (document.fullscreenElement === null)
          void document.documentElement.requestFullscreen?.().catch(() => {});
      } else if (document.fullscreenElement !== null) {
        void document.exitFullscreen?.().catch(() => {});
      }
    } catch {
      // Some browsers throw rather than rejecting; either way this is optional.
    }
  }

  /**
   * Keeps the full-screen playback bar moving.
   *
   * Only one slot is ever full screen, so one clock is enough, and it only runs while there
   * is a bar to write to — twenty players asked for their position twice a second, for a bar
   * nobody is looking at, would be paid for in battery.
   */
  let barTimer: number | null = null;

  function followBar(index: number | null): void {
    if (barTimer !== null) window.clearInterval(barTimer);
    barTimer = null;
    if (index === null) return;
    const entry = built[index];
    if (entry === undefined) return;
    entry.syncBar();
    barTimer = window.setInterval(() => entry.syncBar(), 500);
  }

  function expandSlot(index: number | null): void {
    expanded = index;
    built.forEach((entry, position) => {
      const on = position === index;
      entry.elements.section.classList.toggle('expanded', on);
      if (on) entry.refit();
    });
    document.body.classList.toggle('expanded', index !== null);
    mixerOpen.hidden = index === null;
    requestScreen(index !== null);
    followBar(index);
    wake();
    if (index === null) closeMixer();
    // The drawer lists the *other* slots, so which slot is full screen changes what belongs
    // in it. Leaving it as it was would offer a slider for the picture now on screen.
    else if (!mixer.hidden) fillMixer(index);
  }

  /**
   * Moves full screen to the slot before or after this one, wrapping at the ends.
   *
   * Wrapping rather than stopping: with twenty slots, reaching the far end one swipe at a
   * time is a long way to go, and there is no edge on screen to tell anyone they have
   * arrived at one.
   */
  function showNeighbour(from: number, direction: 'next' | 'previous'): void {
    if (expanded !== from || count < 2) return;
    const step = direction === 'next' ? 1 : -1;
    const next = (from + step + count) % count;
    if (next === from) return;
    expandSlot(next);
    built[next]?.flash(slotName(next, layout));
  }

  /**
   * One row per other slot: its name, a slider, and the number it is on.
   *
   * Rebuilt every time the drawer opens rather than kept in step, because what belongs in it
   * changes with the slot count, the layout's names, and which slots have a video at all —
   * and the drawer is only ever looked at for a moment.
   */
  function fillMixer(expandedIndex: number): void {
    const rows: HTMLElement[] = [];

    built.forEach((entry, index) => {
      // A hidden or empty slot has nothing to hear. The full-screen one does belong here:
      // the operator asked for its own volume in the drawer on 2026-09-22, and dragging up
      // and down the picture to find it is a coarser instrument than a slider.
      if (index >= count) return;
      if (at(index).videoId === null) return;

      const row = document.createElement('label');
      row.className = 'mixer-row';
      if (index === expandedIndex) row.classList.add('mine');
      // A slot that is not playing still belongs here — it is about to be — but it should not
      // look like one of the voices currently in the mix.
      if (!entry.slot.isPlaying()) row.classList.add('silent');

      const name = document.createElement('span');
      name.className = 'mixer-name';
      // Titles come from other people's channels; only ever text, never markup.
      name.textContent =
        index === expandedIndex ? `${slotName(index, layout)}（表示中）` : slotName(index, layout);

      const slider = document.createElement('input');
      slider.type = 'range';
      slider.min = String(MIN_VOLUME);
      slider.max = String(MAX_VOLUME);
      slider.step = '1';
      slider.value = String(at(index).volume);
      slider.setAttribute('aria-label', `${slotName(index, layout)} の音量`);

      const reading = document.createElement('output');
      reading.textContent = slider.value;

      slider.addEventListener('input', () => {
        const applied = entry.setVolume(Number(slider.value));
        reading.textContent = String(applied);
      });

      row.append(name, slider, reading);
      rows.push(row);
    });

    if (rows.length === 0) {
      const empty = document.createElement('p');
      empty.className = 'mixer-empty';
      empty.textContent = '動画の入った枠がありません。';
      mixerList.replaceChildren(empty);
      return;
    }

    mixerList.replaceChildren(...rows);
  }

  function openMixer(): void {
    if (expanded === null) return;
    fillMixer(expanded);
    mixer.hidden = false;
    mixerOpen.setAttribute('aria-expanded', 'true');
    wake();
  }

  function closeMixer(): void {
    mixer.hidden = true;
    mixerOpen.setAttribute('aria-expanded', 'false');
    // Rows hold listeners onto slots; an empty drawer is one less thing to keep in step.
    mixerList.replaceChildren();
    wake();
  }

  function toggleMixer(): void {
    if (mixer.hidden) openMixer();
    else closeMixer();
  }

  mixerOpen.addEventListener('click', toggleMixer);
  must<HTMLButtonElement>(document, '#mixerClose').addEventListener('click', closeMixer);

  /** Going full screen, with a history entry so the device's back gesture can undo it. */
  function openExpanded(index: number): void {
    if (!expandPushedHistory) {
      history.pushState({ ytDualExpanded: true }, '');
      expandPushedHistory = true;
    }
    expandSlot(index);
  }

  /**
   * Leaving full screen from inside the app. The picture is put back first and the history
   * entry dropped after: `history.back()` only reports later, through `popstate`, and waiting
   * for it would leave the slot covering the screen for a frame or two after the tap.
   */
  function closeExpanded(): void {
    expandSlot(null);
    if (expandPushedHistory) {
      expandPushedHistory = false;
      history.back();
    }
  }

  /**
   * The back gesture, or our own `history.back()` reporting in. Either way the entry we pushed
   * is gone, so the flag is cleared whether or not there was anything left to close.
   */
  window.addEventListener('popstate', () => {
    expandPushedHistory = false;
    if (expanded !== null) expandSlot(null);
  });

  /** The highlight only means something on the wall; the pair says 動画 / 音楽 instead. */
  function reflectSelection(): void {
    built.forEach((entry, index) => {
      entry.elements.name.setAttribute(
        'aria-pressed',
        String(layout === 'wall' && index === selected),
      );
    });
  }

  /**
   * Builds any slot that does not exist yet and starts its player. The building half runs
   * before this returns its promise, so a caller may fill the new slots straight away and
   * only wait here if it cares that YouTube has answered.
   */
  function ensureSlots(count: number): Promise<void> {
    const starting: Promise<void>[] = [];
    for (let index = built.length; index < count; index += 1) {
      const entry = buildSlot(index);
      built.push(entry);
      starting.push(entry.slot.start(at(index).videoId));
    }
    return Promise.all(starting).then(() => undefined);
  }

  /**
   * The handles between the columns.
   *
   * There is one per gap, so two columns get one and five get four. Each spans every row,
   * because a column is the full height of the grid however many rows are standing in it.
   * With a single column there is no gap and no handle.
   *
   * Slots are placed by explicit row and column rather than left to flow, because the handles
   * sit in tracks of their own and a flowing slot would land in one of them.
   */
  const splitTemplate = must<HTMLTemplateElement>(document, '#splitTemplate');
  const handles: HTMLElement[] = [];

  function liveColumns(): number {
    return columnsFor(count, window.innerWidth, columns);
  }

  /** The row for this many columns: the operator's, or the one the grid would draw itself. */
  function widthsFor(columnCount: number): number[] {
    return [...(widths[columnCount] ?? evenWidths(columnCount))];
  }

  /** Stamps out or puts away handles so there is exactly one per gap. */
  function ensureHandles(wanted: number): void {
    while (handles.length < wanted) {
      const node = splitTemplate.content.firstElementChild?.cloneNode(true);
      if (!(node instanceof HTMLElement)) break;
      attachHandle(node, handles.length);
      handles.push(node);
    }
    for (const [index, handle] of handles.entries()) {
      const used = index < wanted;
      handle.hidden = !used;
      if (used && handle.parentElement !== host) host.append(handle);
      else if (!used && handle.parentElement === host) handle.remove();
    }
  }

  function reflectSplit(): void {
    const columnCount = liveColumns();
    ensureHandles(Math.max(0, columnCount - 1));

    // Slots first: every one of them, since a hidden slot becomes visible again later.
    built.forEach((entry, index) => {
      const style = entry.elements.section.style;
      style.gridColumn = String((index % columnCount) * 2 + 1);
      style.gridRow = String(Math.floor(index / columnCount) + 1);
    });

    if (columnCount < MIN_COLUMNS_FOR_HANDLE) {
      host.dataset.split = 'off';
      host.style.removeProperty('grid-template-columns');
      return;
    }

    const row = widthsFor(columnCount);
    host.dataset.split = 'on';
    host.style.gridTemplateColumns = row
      .map((share) => `minmax(0, ${Math.round(share * 1000)}fr)`)
      .join(' auto ');

    // Every row: a column is as tall as the whole grid. Counted rather than written as
    // `1 / -1`, which only reaches the last row the stylesheet declared — and the stylesheet
    // declares none, so every row past the first is made on the fly and `-1` stops at row one.
    const rows = Math.max(1, Math.ceil(count / columnCount));

    for (const [index, handle] of handles.entries()) {
      if (index >= columnCount - 1) break;
      handle.style.gridColumn = String(index * 2 + 2);
      handle.style.gridRow = `1 / span ${rows}`;
      const upTo = row.slice(0, index + 1).reduce((sum, share) => sum + share, 0);
      handle.setAttribute('aria-valuenow', String(Math.round(upTo * 100)));
      handle.setAttribute('aria-label', `${index + 1} 本目の仕切り`);
    }
  }

  /** Nothing is written to storage until the finger comes off. */
  function showWidths(columnCount: number, row: readonly number[]): void {
    widths = { ...widths, [columnCount]: row };
    reflectSplit();
    for (const entry of built) entry.refit();
  }

  function setWidths(columnCount: number, row: readonly number[]): void {
    showWidths(columnCount, row);
    save();
  }

  /**
   * Dragging one.
   *
   * The move is measured from where the finger went down, against the widths as they were at
   * that moment — so the handle tracks the finger exactly, and a finger that runs past the
   * limit and comes back picks the handle up again instead of having let go of it.
   */
  interface HandleDrag {
    readonly pointerId: number;
    readonly handle: HTMLElement;
    /** Which gap: 0 is between the first and second columns. */
    readonly boundary: number;
    readonly startX: number;
    readonly columnCount: number;
    readonly startWidths: readonly number[];
    /** The columns' own pixels, with the handles and the gaps between them left out. */
    readonly contentPx: number;
  }
  let drag: HandleDrag | null = null;

  /** Adds up the columns as they are actually drawn, so gaps never enter the arithmetic. */
  function measureContentPx(columnCount: number): number {
    let total = 0;
    for (let column = 0; column < columnCount; column += 1) {
      total += built[column]?.elements.section.getBoundingClientRect().width ?? 0;
    }
    return total;
  }

  function attachHandle(handle: HTMLElement, index: number): void {
    handle.addEventListener('pointerdown', (event) => {
      const columnCount = liveColumns();
      if (drag !== null || index >= columnCount - 1) return;
      const contentPx = measureContentPx(columnCount);
      if (contentPx <= 0) return;
      // No `preventDefault()`: cancelling the press cancels the tap that follows it, and the
      // double tap is the only way back to even. Scrolling is held off by `touch-action` and
      // selecting by `user-select`, which is all it was ever for.
      drag = {
        pointerId: event.pointerId,
        handle,
        boundary: index,
        startX: event.clientX,
        columnCount,
        startWidths: widthsFor(columnCount),
        contentPx,
      };
      // Capture keeps the moves coming when the finger outruns a 14px target. A convenience,
      // not the mechanism — the listeners below are on the window either way.
      try {
        handle.setPointerCapture(event.pointerId);
      } catch {
        // Some browsers refuse to capture a pointer they no longer consider active.
      }
      handle.classList.add('dragging');
    });

    /** The way back to even. A dragged handle cannot find the middle again by eye. */
    handle.addEventListener('dblclick', () => {
      const columnCount = liveColumns();
      if (columnCount < MIN_COLUMNS_FOR_HANDLE) return;
      setWidths(columnCount, evenWidths(columnCount));
    });

    /** It is focusable, so the arrows have to do something. One press is a twentieth. */
    handle.addEventListener('keydown', (event) => {
      const columnCount = liveColumns();
      if (index >= columnCount - 1) return;
      const row = widthsFor(columnCount);
      if (event.key === 'ArrowLeft') setWidths(columnCount, dragWidths(row, index, -SPLIT_STEP));
      else if (event.key === 'ArrowRight') {
        setWidths(columnCount, dragWidths(row, index, SPLIT_STEP));
      } else if (event.key === 'Home' || event.key === 'End') {
        setWidths(columnCount, evenWidths(columnCount));
      } else return;
      event.preventDefault();
    });
  }

  window.addEventListener('pointermove', (event) => {
    if (drag === null || drag.pointerId !== event.pointerId) return;
    const moved = (event.clientX - drag.startX) / drag.contentPx;
    showWidths(drag.columnCount, dragWidths(drag.startWidths, drag.boundary, moved));
  });

  const endHandleDrag = (event: PointerEvent): void => {
    if (drag === null || drag.pointerId !== event.pointerId) return;
    drag.handle.classList.remove('dragging');
    drag = null;
    save();
  };
  window.addEventListener('pointerup', endHandleDrag);
  window.addEventListener('pointercancel', endHandleDrag);

  /** The stylesheet cannot put a number inside `repeat()`, so the answer arrives as a property. */
  function reflectColumns(): void {
    host.style.setProperty('--columns', String(liveColumns()));
    reflectSplit();
    // The menu is only about the wall; one or two slots have nothing to arrange.
    columnsSelect.hidden = layout !== 'wall';
    columnsSelect.value = columns === null ? 'auto' : String(columns);
  }
  window.addEventListener('resize', reflectColumns);

  columnsSelect.addEventListener('change', () => {
    columns = columnsSelect.value === 'auto' ? null : Number(columnsSelect.value);
    reflectColumns();
    save();
  });

  function applyCount(): void {
    layout = layoutFor(count);
    host.dataset.layout = layout;

    // A slot that is about to be hidden cannot stay covering the page. This drops the history
    // entry too — leaving it would make the next back gesture close nothing visible.
    if (expanded !== null && expanded >= count) closeExpanded();

    built.forEach((entry, index) => {
      const visible = index < count;
      // A player nobody can see must not keep singing.
      if (!visible && !entry.elements.section.hidden) entry.slot.pause();
      entry.elements.section.hidden = !visible;
      entry.elements.name.textContent = slotName(index, layout);
      // Whether an empty slot shows its address box depends on which layout it is in.
      entry.reflectPaste();
    });

    if (selected >= count) selected = 0;
    reflectSelection();
    reflectColumns();
    range.value = String(count);
    countValue.value = String(count);
  }

  /** Changes how many slots are on screen, building any that do not exist yet. */
  function setCount(next: number): void {
    count = clampCount(next);
    const started = ensureSlots(count);
    applyCount();
    save();
    started.catch(() => {
      note.textContent = '枠をすべては用意できませんでした。';
    });
  }

  range.addEventListener('input', () => {
    setCount(Number(range.value));
  });
  must<HTMLButtonElement>(document, '#countDown').addEventListener('click', () => {
    setCount(count - 1);
  });
  must<HTMLButtonElement>(document, '#countUp').addEventListener('click', () => {
    setCount(count + 1);
  });

  const visible = (): BuiltSlot[] => built.slice(0, count);

  must<HTMLButtonElement>(document, '#playBoth').addEventListener('click', () => {
    for (const entry of visible()) entry.slot.play();
  });
  must<HTMLButtonElement>(document, '#pauseBoth').addEventListener('click', () => {
    for (const entry of visible()) entry.slot.pause();
  });

  /*
   * Emptying every slot, including the ones the count is currently hiding — a slot nobody can
   * see is exactly the one that gets forgotten about and then surprises the operator when the
   * count goes back up.
   *
   * The button asks twice. There is no undo, and the second tap costs a second where a dialog
   * costs reading; the offer expires so it cannot be answered by accident tomorrow.
   *
   * Armed, it turns red and says so in the note. It used to rewrite its own label, which a
   * button carrying one glyph cannot do — and the label was inside the button, which is the
   * one place a hand about to press it is not reading.
   */
  const resetAll = must<HTMLButtonElement>(document, '#resetAll');
  const RESET_CONFIRM_MS = 4000;
  let resetArmed: number | null = null;

  const disarmReset = (): void => {
    if (resetArmed !== null) window.clearTimeout(resetArmed);
    resetArmed = null;
    resetAll.classList.remove('armed');
  };

  resetAll.addEventListener('click', () => {
    if (resetArmed === null) {
      resetAll.classList.add('armed');
      note.textContent = 'もう一度 🧹 を押すと、全部の枠が空になります。';
      resetArmed = window.setTimeout(disarmReset, RESET_CONFIRM_MS);
      return;
    }
    disarmReset();
    closeExpanded();
    for (const entry of built) entry.reset();
    selected = 0;
    reflectSelection();
    save();
    note.textContent = '全部の枠を空にしました。';
  });

  wireLibrary(note, {
    place: (videoId, target) => {
      const index = target === 'video' ? 0 : target === 'music' ? 1 : selected;
      const entry = built[index];
      if (entry === undefined) return '';
      entry.load(videoId);
      const name = slotName(index, layout);
      if (target === 'next') {
        // Advance, so filling the wall is one tap per slot on the list and nothing else.
        selected = (index + 1) % count;
        reflectSelection();
      }
      return `${name} に入れました。`;
    },
    fillAll: (videoIds) => {
      const ids = videoIds.slice(0, MAX_SLOTS);
      if (ids.length === 0) return '入れられる動画がありません。';
      // Being handed a list and shown less of it than there is would be a strange answer.
      if (ids.length > count) setCount(ids.length);
      ids.forEach((videoId, index) => {
        built[index]?.load(videoId);
      });
      selected = Math.min(ids.length, count - 1);
      reflectSelection();
      return `上から ${ids.length} 枠に入れました。`;
    },
    layout: () => layout,
  });

  try {
    const started = ensureSlots(count);
    applyCount();
    await started;
  } catch (error) {
    note.textContent =
      error instanceof Error
        ? `プレイヤーを用意できません: ${error.message}`
        : 'プレイヤーを用意できません';
  }
}
