/**
 * How many slots stand side by side.
 *
 * This is the one place that decides it. The stylesheet used to hold the same knowledge as a
 * pair of breakpoints, which was fine while there were exactly two screens to describe; with
 * the count now anything from one to twenty, the rule has to read the count, and CSS cannot
 * put a variable inside `repeat()`. So it lives here as a plain function, gets tested, and
 * reaches the stylesheet as a single custom property.
 *
 * Left alone, the grid comes out as close to square as the count allows — nine slots make
 * three rows of three, twelve make three rows of four. The operator can override it, and then
 * their number wins on every screen; the automatic answer is the one that shrinks to fit.
 *
 * The widths match the ones the stylesheet still uses for the picker column, on purpose: at
 * 700 the picker moves out beside the players, and at 900 there is room for two of them.
 */

import { PAIR_SLOTS, WALL_COLUMNS } from '../core/session.js';

export const WIDE_WIDTH = 900;
export const MEDIUM_WIDTH = 700;

/** Caps below the widest screen. Five small players on a phone would each be a postage stamp. */
const MEDIUM_COLUMNS = 3;
const NARROW_COLUMNS = 2;

function capForWidth(width: number): number {
  if (width >= WIDE_WIDTH) return WALL_COLUMNS;
  if (width >= MEDIUM_WIDTH) return MEDIUM_COLUMNS;
  return NARROW_COLUMNS;
}

/**
 * The squarest grid that holds `count`, preferring the slightly wider one when it comes out
 * even. Screens are wider than they are tall, and a last row with one slot in it looks like a
 * mistake: eight slots read better as four and four than as three, three and two.
 */
export function squarestColumns(count: number): number {
  const wanted = Math.max(1, Math.round(count));
  const square = Math.ceil(Math.sqrt(wanted));
  if (wanted % square !== 0 && square + 1 <= WALL_COLUMNS && wanted % (square + 1) === 0) {
    return square + 1;
  }
  return Math.min(square, WALL_COLUMNS);
}

/**
 * `chosen` is the operator's own column count, or `null` to work it out from `count`.
 * Never returns more columns than there are slots, whichever way the answer was reached.
 */
export function columnsFor(count: number, width: number, chosen: number | null = null): number {
  const wanted = Math.max(1, Math.round(count));

  if (chosen !== null) return Math.min(wanted, Math.max(1, Math.round(chosen)));

  // One or two slots keep the roomy shape the app was built around: stacked until there is
  // real room, never squeezed side by side on a phone.
  if (wanted <= PAIR_SLOTS) return width >= WIDE_WIDTH ? wanted : 1;

  return Math.min(squarestColumns(wanted), capForWidth(width));
}
