/**
 * Loading the IFrame Player API exactly once.
 *
 * The API hands control back through a single global callback, so two callers racing for it
 * would clobber each other. Everything goes through one promise instead.
 */

import type { YouTubeNamespace } from './types.js';

const SCRIPT_URL = 'https://www.youtube.com/iframe_api';
const SCRIPT_ID = 'youtube-iframe-api';

let pending: Promise<YouTubeNamespace> | null = null;

export function loadIframeApi(): Promise<YouTubeNamespace> {
  if (pending !== null) return pending;

  pending = new Promise<YouTubeNamespace>((resolve, reject) => {
    const existing = window.YT;
    if (existing !== undefined) {
      resolve(existing);
      return;
    }

    window.onYouTubeIframeAPIReady = () => {
      const namespace = window.YT;
      if (namespace === undefined) {
        reject(new Error('YouTube said it was ready but left no player factory behind'));
        return;
      }
      resolve(namespace);
    };

    if (document.getElementById(SCRIPT_ID) !== null) return;

    const script = document.createElement('script');
    script.id = SCRIPT_ID;
    script.src = SCRIPT_URL;
    script.async = true;
    script.onerror = () => {
      reject(new Error(`Could not load ${SCRIPT_URL}`));
    };
    document.head.append(script);
  });

  return pending;
}
